'use strict';
const $=s=>document.querySelector(s),form=$('#search-form'),input=$('#student-name'),button=$('#search-button'),clear=$('#clear-search'),department=$('#department'),results=$('#results'),status=$('#load-status'),hint=$('#search-hint'),announcement=$('#search-announcement');
const {normalize,prepareStudents,findStudents}=AdmissionSearch;
const initial=results.firstElementChild.cloneNode(true),defaultHint=hint.textContent,PAGE_SIZE=20;
let records=[],ready=false,queryTimer,toastTimer;
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
function notify(message){const toast=$('#toast');clearTimeout(toastTimer);toast.textContent=message;toast.hidden=false;toastTimer=setTimeout(()=>{toast.hidden=true;},3000);}
function empty(title,body){const card=el('div','message-card');card.append(el('span','message-icon','⌕'),el('h3','',title),el('p','',body));results.replaceChildren(card);announcement.textContent=title;}
function reset(){results.replaceChildren(initial.cloneNode(true));announcement.textContent='';hint.textContent=defaultHint;hint.classList.remove('is-error');}
function resultCard(student,query){const card=el('article','result-card');card.tabIndex=-1;const top=el('div','result-top');top.append(el('span','acceptance-badge','✓ مرشح للقبول'),el('span','result-year','2026 / 2027'));const name=el('h3','student-name',student.name);const studentHeading='student-'+student.id;name.id=studentHeading;card.setAttribute('aria-labelledby',studentHeading);const departmentBlock=el('div','department-result');departmentBlock.append(el('span','department-label','القسم المرشح للقبول'),el('strong','department-name',student.department));const bottom=el('div','result-bottom');bottom.append(el('span','study-tag','الدراسة المسائية'));const actions=el('div','result-actions');const copy=el('button','result-button','نسخ النتيجة');copy.type='button';copy.setAttribute('aria-label','نسخ نتيجة '+student.name);copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(student.name+'\nالقسم المرشح للقبول: '+student.department+'\nالدراسة المسائية — 2026/2027');notify('تم نسخ النتيجة');}catch{notify('تعذّر النسخ. يمكنك تحديد نص النتيجة ونسخه.');}});const print=el('button','result-button','طباعة ↗');print.type='button';print.setAttribute('aria-label','طباعة نتيجة '+student.name);print.addEventListener('click',()=>{document.querySelectorAll('.printing').forEach(n=>n.classList.remove('printing'));card.classList.add('printing');window.print();});actions.append(copy,print);bottom.append(actions);card.append(top,name,departmentBlock,bottom);if(student.key===normalize(query).replace(/ /g,''))card.classList.add('exact-match');return card;}
function showMatches(matches,query){results.replaceChildren();const header=el('div','results-heading');header.append(el('span','overline','نتيجة الاستعلام'),el('h2','',matches.length===1?'أهلاً بخطوتك الجديدة':'الأسماء المطابقة لبحثك'));results.append(header);if(matches.length>1)results.append(el('p','results-hint','اختر النتيجة المطابقة لاسمك الكامل، أو أضف اسم الأب والجد لتحديدها.'));const list=el('div','result-list');results.append(list);let shown=0;const more=el('button','more-button','عرض المزيد من الأسماء');more.type='button';function page(byClick){const start=shown;matches.slice(start,start+PAGE_SIZE).forEach(s=>list.append(resultCard(s,query)));shown=Math.min(start+PAGE_SIZE,matches.length);if(shown===matches.length)more.remove();if(byClick)list.children[start].focus({preventScroll:true});}more.addEventListener('click',()=>page(true));results.append(more);page(false);announcement.textContent=matches.length===1?'ظهرت نتيجة الترشيح':'ظهرت أسماء مطابقة للبحث. تحقق من اسمك الكامل.';}
function run(explicit=false){if(!ready)return;const query=input.value.trim();clear.hidden=!input.value;if(normalize(query).replace(/ /g,'').length<2){reset();if(explicit){hint.textContent='اكتب حرفين على الأقل من اسمك.';hint.classList.add('is-error');input.focus();}return;}hint.textContent=defaultHint;hint.classList.remove('is-error');const matches=findStudents(records,query,department.value);if(matches.length)showMatches(matches,query);else empty('لم نعثر على اسم مطابق','جرّب كتابة جزء من اسمك أو اختيار جميع الأقسام. إذا لم يظهر اسمك، راجع شعبة التسجيل وشؤون الطلبة. عدم ظهور الاسم لا يعني رفض القبول.');if(explicit){results.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}}
async function load(){if(status.dataset.loading==='true')return;status.dataset.loading='true';ready=false;input.disabled=button.disabled=department.disabled=true;$('#ready-badge').hidden=true;status.classList.remove('is-error');status.textContent='جارٍ تجهيز البحث…';const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const response=await fetch('students.json',{cache:'no-cache',signal:controller.signal});if(!response.ok)throw new Error('http');const data=await response.json();if(!Array.isArray(data)||!data.length||data.some(r=>typeof r.name!=='string'||!r.name.trim()||typeof r.department!=='string'||!r.department.trim()))throw new Error('data');records=prepareStudents(data);department.replaceChildren(el('option','','جميع الأقسام'));department.firstElementChild.value='';for(const name of [...new Set(data.map(s=>s.department))].sort((a,b)=>a.localeCompare(b,'ar'))){const option=el('option','',name);option.value=name;department.append(option);}ready=true;input.disabled=button.disabled=department.disabled=false;$('#ready-badge').hidden=false;status.textContent='';if(input.value)run();}catch{status.classList.add('is-error');status.replaceChildren(el('span','','تعذّر تجهيز البحث. تحقق من اتصالك وأعد المحاولة.'));const retry=el('button','retry-button','إعادة المحاولة');retry.type='button';retry.addEventListener('click',load);status.append(retry);}finally{clearTimeout(timeout);status.dataset.loading='false';}}
form.addEventListener('submit',e=>{e.preventDefault();clearTimeout(queryTimer);run(true);});input.addEventListener('input',()=>{clearTimeout(queryTimer);clear.hidden=!input.value;queryTimer=setTimeout(()=>run(),160);});clear.addEventListener('click',()=>{clearTimeout(queryTimer);input.value='';clear.hidden=true;reset();input.focus();});department.addEventListener('change',()=>{clearTimeout(queryTimer);run();});window.addEventListener('afterprint',()=>document.querySelectorAll('.printing').forEach(n=>n.classList.remove('printing')));load();
